import{_ as r,C as i,o,c as g,a3 as d,j as e,a as l,E as s,w as a}from"./chunks/framework.bvEHUNtb.js";const m=JSON.parse('{"title":"18 五音十二律","description":"从五音、十二律与三分损益法，理解传统音律如何连接五行、节气与时间秩序。","frontmatter":{"title":"18 五音十二律","description":"从五音、十二律与三分损益法，理解传统音律如何连接五行、节气与时间秩序。","category":"guide","outline":"deep","aliases":["五音十二律","五音六律","十二律吕"]},"headers":[],"relativePath":"topics/traditional-wisdom/energy/five-tones-twelve-pitches.md","filePath":"topics/traditional-wisdom/energy/five-tones-twelve-pitches.md","lastUpdated":1786982540000}'),x={name:"topics/traditional-wisdom/energy/five-tones-twelve-pitches.md"},f={tabindex:"0"},y={style:{"text-align":"left"}},p={style:{"text-align":"left"}};function h(b,t,u,q,c,k){const n=i("font");return o(),g("div",null,[t[16]||(t[16]=d('<h1 id="_18-·-五音十二律-声音与时间的秩序" tabindex="-1">18 · 五音十二律：声音与时间的秩序 <a class="header-anchor" href="#_18-·-五音十二律-声音与时间的秩序" aria-label="Permalink to &quot;18 · 五音十二律：声音与时间的秩序&quot;">​</a></h1><p><strong>系列：</strong> 中华传统智慧体系 · 通识基础知识库 · 第四阶段·能量状态系统<br><strong>版本：</strong> v2.0（2026年7月）<br><strong>前置篇目：</strong> 04·五行论 / 11·十天干 / 14·二十四节气<br><strong>后续篇目：</strong> 纳音五行（后续；本篇底层结构的直接应用）<br><strong>C系列关联：</strong> C-07·五音十二律（三分损益法完整数学推导·律数精解）</p><hr><h2 id="写在前面-一个名词辨析" tabindex="-1">写在前面：一个名词辨析 <a class="header-anchor" href="#写在前面-一个名词辨析" aria-label="Permalink to &quot;写在前面：一个名词辨析&quot;">​</a></h2><p>本篇标题为&quot;<strong>五音十二律</strong>&quot;，但也有五音六律的说法。<br> 初读者可能会困惑：六律和十二律，是同一件事吗？</p><p><strong>是的，但需要辨析：</strong></p>',6)),e("table",f,[t[10]||(t[10]=e("thead",null,[e("tr",null,[e("th",{style:{"text-align":"left"}},"说法"),e("th",{style:{"text-align":"left"}},"所指"),e("th",{style:{"text-align":"left"}},"出处")])],-1)),e("tbody",null,[t[7]||(t[7]=e("tr",null,[e("td",{style:{"text-align":"left"}},[e("strong",null,"六律"),l("（狭义）")]),e("td",{style:{"text-align":"left"}},[l("仅六个"),e("strong",null,"阳"),l("律：黄钟·太簇·姑洗·蕤宾·夷则·无射")]),e("td",{style:{"text-align":"left"}},'《周礼·春官》"六律六同"')],-1)),t[8]||(t[8]=e("tr",null,[e("td",{style:{"text-align":"left"}},[e("strong",null,"六同"),l("（或六吕）")]),e("td",{style:{"text-align":"left"}},[l("仅六个"),e("strong",null,"阴"),l("律：大吕·夹钟·仲吕·林钟·南吕·应钟")]),e("td",{style:{"text-align":"left"}},"同上")],-1)),e("tr",null,[t[6]||(t[6]=e("td",{style:{"text-align":"left"}},[e("strong",null,"六律"),l("（广义）")],-1)),e("td",y,[t[1]||(t[1]=l("十二律吕的",-1)),t[2]||(t[2]=e("strong",null,"统称",-1)),t[3]||(t[3]=l("，以阳统阴，六律代指全部十二律。",-1)),t[4]||(t[4]=e("br",null,null,-1)),s(n,{style:{color:"rgb(89, 89, 89)"}},{default:a(()=>[...t[0]||(t[0]=[l('《汉书·律历志》："黄帝使泠纶……制十二筒……以别十二律，其雄鸣为六，雌鸣亦六，比黄钟之宫，而皆可以生之，是为律本。',-1)])]),_:1})]),e("td",p,[s(n,{style:{color:"rgb(89, 89, 89)"}},{default:a(()=>[...t[5]||(t[5]=[l('此处"六律"统领全部十二律，是广义用法的典型文献依据。',-1)])]),_:1})])]),t[9]||(t[9]=e("tr",null,[e("td",{style:{"text-align":"left"}},[e("strong",null,"十二律")]),e("td",{style:{"text-align":"left"}},"六律 + 六吕，共十二个音级的完整表述"),e("td",{style:{"text-align":"left"}},"《汉书·律历志》")],-1))])]),t[17]||(t[17]=d(`<blockquote><p>【原典】《史记·律书》<br> 【原文】&quot;王者制事立法，物度轨则，壹禀于六律，六律为万事根本焉。&quot;<br> 【版本】西汉·司马迁撰（中国哲学书电子化计划·史记·律书）</p></blockquote><p>司马迁这里的&quot;六律&quot;，指的正是十二律吕的全体——<br> 这是古籍中以阳统阴、以六代十二的惯用表达。</p><p><strong>正文中凡涉及完整音律体系，均以&quot;十二律&quot;表述，以求准确。</strong></p><hr><h2 id="一、俯瞰-它在整个体系里的位置" tabindex="-1">一、俯瞰：它在整个体系里的位置 <a class="header-anchor" href="#一、俯瞰-它在整个体系里的位置" aria-label="Permalink to &quot;一、俯瞰：它在整个体系里的位置&quot;">​</a></h2><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>道（01）</span></span>
<span class="line"><span>  └─ 阴阳（02）</span></span>
<span class="line"><span>       └─ 五行（04）</span></span>
<span class="line"><span>            ├─ 五方·五季·五脏……（五行的各维度投影）</span></span>
<span class="line"><span>            └─ 五音（宫商角徵羽）← 五行在&quot;声音&quot;维度的投影</span></span>
<span class="line"><span>                 └─ 十二律吕（黄钟·大吕……）← 五音的精细时间坐标</span></span>
<span class="line"><span>                      └─ 六十甲子（13）× 十二律 × 五音</span></span>
<span class="line"><span>                           └─ 纳音五行（19）← 本篇的直接应用出口</span></span></code></pre></div><p><strong>一句话定位：</strong><br> 五音六律，是先人将<strong>声音</strong>纳入宇宙体系的方式——用音律的振动，描述天地之气在时间中的运行节律。<br> 它是<strong>五行哲学</strong>与<strong>时间历法</strong>之间的桥梁，是读懂<strong>纳音五行</strong>、<strong>礼乐制度</strong>、<strong>黄帝内经</strong>、<strong>古代历法</strong>的底层背景。</p><blockquote><p><strong>为什么先学这篇，再学纳音五行？</strong><br> 因为纳音五行的全部推算逻辑，建立在&quot;十二律 × 五音 = 60&quot;这一数学结构之上。<br> 不懂五音六律，纳音就只是一张死记硬背的表格，而不是一套有根有源的活的体系。</p></blockquote><h2 id="二、五音-宇宙的五种声音频率" tabindex="-1">二、五音：宇宙的五种声音频率 <a class="header-anchor" href="#二、五音-宇宙的五种声音频率" aria-label="Permalink to &quot;二、五音：宇宙的五种声音频率&quot;">​</a></h2><h3 id="_2-1-五音是什么" tabindex="-1">2.1 五音是什么？ <a class="header-anchor" href="#_2-1-五音是什么" aria-label="Permalink to &quot;2.1 五音是什么？&quot;">​</a></h3><p>五音，即：<strong>宫、商、角、徵、羽</strong>。</p><p>这是中国古代音乐的<strong>五声音阶</strong>，<br> 对应现代西方音乐的 Do·Re·Mi·Sol·La（去掉 Fa 和 Si）。</p><p>但在传统文化体系里，五音绝不只是音乐概念——<br> 它是<strong>五行在声音维度的完整投影</strong>，<br> 是天地之气的五种振动形态。</p><p>先人的逻辑是这样的：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>天地之气，有五种基本状态（五行）</span></span>
<span class="line"><span>五行各有其声，声音也有五种基本形态（五音）</span></span>
<span class="line"><span>五行与五音，是同一件事的两种表达：</span></span>
<span class="line"><span>  一个是&quot;气&quot;的语言，一个是&quot;声&quot;的语言</span></span></code></pre></div><h3 id="_2-2-五音的字义-每个字都有深意" tabindex="-1">2.2 五音的字义：每个字都有深意 <a class="header-anchor" href="#_2-2-五音的字义-每个字都有深意" aria-label="Permalink to &quot;2.2 五音的字义：每个字都有深意&quot;">​</a></h3><p>五音的命名，不是随意的。每个字，都是一幅小小的宇宙图像。</p><blockquote><p>【原典】《白虎通·礼乐》<br> 【原文】&quot;宫者，中也，居中央，畅四方，唱始施生，为四声纲也。商者，章也，物成章明也。角者，触也，象诸阳气触动而生也。徵者，止也，阳气止而收也。羽者，舒也，阳气将复，万物各舒散而出也。&quot;<br> 【版本】东汉·班固撰</p></blockquote><p>逐字解读：</p><table tabindex="0"><thead><tr><th style="text-align:left;">五音</th><th style="text-align:left;">字义（《白虎通》）</th><th style="text-align:left;">对应的宇宙意象</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>宫</strong></td><td style="text-align:left;">&quot;中也&quot;，居中统领</td><td style="text-align:left;">土居中央，君王之位，四音之纲</td></tr><tr><td style="text-align:left;"><strong>商</strong></td><td style="text-align:left;">&quot;章也&quot;，物成章明</td><td style="text-align:left;">金气收敛，万物成熟显章，秋之声</td></tr><tr><td style="text-align:left;"><strong>角</strong></td><td style="text-align:left;">&quot;触也&quot;，阳气触动而生</td><td style="text-align:left;">木气升发，如嫩芽破土而出，春之声</td></tr><tr><td style="text-align:left;"><strong>徵</strong></td><td style="text-align:left;">&quot;止也&quot;，阳气止而收</td><td style="text-align:left;">火气炎上至极而将收，夏之声</td></tr><tr><td style="text-align:left;"><strong>羽</strong></td><td style="text-align:left;">&quot;舒也&quot;，万物各舒散而出</td><td style="text-align:left;">水气潜藏，阳气将复，冬之声</td></tr></tbody></table><p>这五个字，描述的正是一年之气从萌发（角·春）→ 炎盛（徵·夏）→ 收敛（商·秋）→ 潜藏（羽·冬），以土（宫）居中统御的完整周期。</p><h3 id="_2-3-五音与五行·五方·五季·五脏的完整对应" tabindex="-1">2.3 五音与五行·五方·五季·五脏的完整对应 <a class="header-anchor" href="#_2-3-五音与五行·五方·五季·五脏的完整对应" aria-label="Permalink to &quot;2.3 五音与五行·五方·五季·五脏的完整对应&quot;">​</a></h3><p>这是传统文化体系中最重要的跨维度对应表之一，<br> 出现在《黄帝内经》《礼记·月令》《淮南子·天文训》等多部经典中：</p><blockquote><p>【原典】《黄帝内经·素问·阴阳应象大论》<br> 【原文】&quot;东方生风，风生木……在音为角……南方生热，热生火……在音为徵……中央生湿，湿生土……在音为宫……西方生燥，燥生金……在音为商……北方生寒，寒生水……在音为羽。&quot;<br> 【版本】唐·王冰注本（《重广补注黄帝内经素问》）</p></blockquote><blockquote><p>【原典】《礼记·月令》<br> 【原文】&quot;孟春之月……其音角……孟夏之月……其音徵……中央土……其音宫……孟秋之月……其音商……孟冬之月……其音羽。&quot;<br> 【版本】西汉·戴圣编，郑玄注本</p></blockquote><table tabindex="0"><thead><tr><th style="text-align:left;">五音</th><th style="text-align:left;">五行</th><th style="text-align:left;">五方</th><th style="text-align:left;">五季</th><th style="text-align:left;">五脏</th><th style="text-align:left;">五色</th><th style="text-align:left;">现代音近似</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>宫</strong></td><td style="text-align:left;">土</td><td style="text-align:left;">中央</td><td style="text-align:left;">长夏</td><td style="text-align:left;">脾</td><td style="text-align:left;">黄</td><td style="text-align:left;">Do（1）</td></tr><tr><td style="text-align:left;"><strong>商</strong></td><td style="text-align:left;">金</td><td style="text-align:left;">西方</td><td style="text-align:left;">秋</td><td style="text-align:left;">肺</td><td style="text-align:left;">白</td><td style="text-align:left;">Re（2）</td></tr><tr><td style="text-align:left;"><strong>角</strong></td><td style="text-align:left;">木</td><td style="text-align:left;">东方</td><td style="text-align:left;">春</td><td style="text-align:left;">肝</td><td style="text-align:left;">青</td><td style="text-align:left;">Mi（3）</td></tr><tr><td style="text-align:left;"><strong>徵</strong></td><td style="text-align:left;">火</td><td style="text-align:left;">南方</td><td style="text-align:left;">夏</td><td style="text-align:left;">心</td><td style="text-align:left;">赤</td><td style="text-align:left;">Sol（5）</td></tr><tr><td style="text-align:left;"><strong>羽</strong></td><td style="text-align:left;">水</td><td style="text-align:left;">北方</td><td style="text-align:left;">冬</td><td style="text-align:left;">肾</td><td style="text-align:left;">黑</td><td style="text-align:left;">La（6）</td></tr></tbody></table><blockquote><p>⚠️ <strong>说明：</strong><br> 五音与现代音阶的对应，历代学者有不同说法，此处仅为方便现代读者理解的近似对照，不代表古今音高完全等同。</p></blockquote><h3 id="_2-4-五音与五脏-《内经》的音乐疗愈观" tabindex="-1">2.4 五音与五脏：《内经》的音乐疗愈观 <a class="header-anchor" href="#_2-4-五音与五脏-《内经》的音乐疗愈观" aria-label="Permalink to &quot;2.4 五音与五脏：《内经》的音乐疗愈观&quot;">​</a></h3><p>《黄帝内经》将五音与五脏直接对应，<br> 形成了中医音乐疗愈的理论基础：</p><ul><li><strong>宫音</strong>（土·脾）：音调平和，有助于脾胃运化，安定中焦</li><li><strong>商音</strong>（金·肺）：音调铿锵，有助于肺气宣降，清肃收敛</li><li><strong>角音</strong>（木·肝）：音调升发，有助于肝气疏泄，条达情志</li><li><strong>徵音</strong>（火·心）：音调明亮，有助于心神振奋，气血流通</li><li><strong>羽音</strong>（水·肾）：音调深沉，有助于肾精收藏，宁心安神</li></ul><p>这不是玄学，这是先人对<strong>声音振动与人体共鸣</strong>的系统观察。<br> 现代声学研究也证实：不同频率的声波，确实对人体不同器官和神经系统有不同的影响。<br> 先人早在两千年前，已经建立了这套对应体系。</p><h2 id="三、十二律-将一年切分为十二个声音坐标" tabindex="-1">三、十二律：将一年切分为十二个声音坐标 <a class="header-anchor" href="#三、十二律-将一年切分为十二个声音坐标" aria-label="Permalink to &quot;三、十二律：将一年切分为十二个声音坐标&quot;">​</a></h2><h3 id="_3-1-什么是-律" tabindex="-1">3.1 什么是&quot;律&quot;？ <a class="header-anchor" href="#_3-1-什么是-律" aria-label="Permalink to &quot;3.1 什么是&quot;律&quot;？&quot;">​</a></h3><blockquote><p>【原典】《史记·律书》<br> 【原文】&quot;律者，所以立均出度也。古之圣人，怀天地之道，抱万物之情，和阴阳之气，以律吕之法，通天地之变。&quot;<br> 【版本】西汉·司马迁撰</p></blockquote><p>&quot;律&quot;，是<strong>度量</strong>的工具。<br> &quot;立均&quot;——建立均衡的标准；<br> &quot;出度&quot;——推导出度量的尺度。</p><p>先人用&quot;律&quot;来做什么？<br><strong>用来度量天地之气的变化节律。</strong></p><p>律管，是一根特定长度的竹管或铜管。<br> 不同长度的管，发出不同高度的音。<br> 一年十二个月，天地之气各有不同，<br> 先人为每个月配一根律管，<br> 用音高来标定这个月天地之气的&quot;频率&quot;。</p><p>这就是十二律的本质：<br><strong>十二根律管，是感知天地十二月节律的精密仪器。</strong></p><h3 id="_3-2-十二律的来源-伶伦截竹" tabindex="-1">3.2 十二律的来源：伶伦截竹 <a class="header-anchor" href="#_3-2-十二律的来源-伶伦截竹" aria-label="Permalink to &quot;3.2 十二律的来源：伶伦截竹&quot;">​</a></h3><blockquote><p>【原典】《吕氏春秋·古乐篇》<br> 【原文】&quot;昔黄帝令伶伦作为律。伶伦自大夏之西，乃之阮隃之阴，取竹于嶰溪之谷，以生空窍厚钧者，断两节间，其长三寸九分，而吹之，以为黄钟之宫，吹曰&#39;舍少&#39;。次制十二筒，以之阮隃之下，听凤凰之鸣，以别十二律。&quot;<br> 【版本】战国·吕不韦撰（《吕氏春秋》）</p></blockquote><p>这段记载，是十二律起源最重要的传说文献：</p><ul><li>黄帝命乐官<strong>伶伦</strong>制律</li><li>伶伦到昆仑山北麓的嶰溪谷，取竹截管</li><li>第一根管，长<strong>三寸九分</strong>，吹出<strong>黄钟</strong>之音</li><li>再制十二管，以<strong>凤凰鸣声</strong>为标准，定出十二律</li></ul><p>这当然是神话叙事，但它传递了一个重要信息：<br><strong>十二律的标准，来自对自然之声的聆听与模仿。</strong><br> 先人不是凭空发明音律，而是从天地自然的声音中，提炼出了这套描述宇宙节律的语言。</p><h3 id="_3-3-六律与六吕-阴阳各六" tabindex="-1">3.3 六律与六吕：阴阳各六 <a class="header-anchor" href="#_3-3-六律与六吕-阴阳各六" aria-label="Permalink to &quot;3.3 六律与六吕：阴阳各六&quot;">​</a></h3><p>十二律分为阴阳两组：</p><blockquote><p>【原典】《周礼·春官·大司乐》<br> 【原文】&quot;大司乐……以六律、六同、五声、八音、六舞，大合乐。&quot;<br> 【版本】郑玄注本（东汉）</p></blockquote><p>郑玄注：&quot;六律，阳声也：黄钟·太簇·姑洗·蕤宾·夷则·无射。六同，阴声也：大吕·夹钟·仲吕·林钟·南吕·应钟。&quot;</p><table tabindex="0"><thead><tr><th style="text-align:left;">组别</th><th style="text-align:left;">名称</th><th style="text-align:left;">阴阳</th><th style="text-align:left;">六个律名</th></tr></thead><tbody><tr><td style="text-align:left;">六律</td><td style="text-align:left;">阳律</td><td style="text-align:left;">阳</td><td style="text-align:left;">黄钟·太簇·姑洗·蕤宾·夷则·无射</td></tr><tr><td style="text-align:left;">六同（六吕）</td><td style="text-align:left;">阴律</td><td style="text-align:left;">阴</td><td style="text-align:left;">大吕·夹钟·仲吕·林钟·南吕·应钟</td></tr></tbody></table><p>阳律主&quot;施&quot;（发出），阴律主&quot;应&quot;（回应）——<br> 阴阳相和，才构成完整的天地之音。</p><h3 id="_3-4-十二律吕完整对照表" tabindex="-1">3.4 十二律吕完整对照表 <a class="header-anchor" href="#_3-4-十二律吕完整对照表" aria-label="Permalink to &quot;3.4 十二律吕完整对照表&quot;">​</a></h3><blockquote><p>【原典】《淮南子·天文训》<br> 【原文】&quot;十一月，律中黄钟……十二月，律中大吕……正月，律中太簇……二月，律中夹钟……三月，律中姑洗……四月，律中仲吕……五月，律中蕤宾……六月，律中林钟……七月，律中夷则……八月，律中南吕……九月，律中无射……十月，律中应钟。&quot;<br> 【版本】西汉·刘安撰，高诱注本（中国哲学书电子化计划·淮南子·天文训）</p></blockquote><table tabindex="0"><thead><tr><th style="text-align:left;">序</th><th style="text-align:left;">律名</th><th style="text-align:left;">阴阳</th><th style="text-align:left;">月份</th><th style="text-align:left;">地支</th><th style="text-align:left;">节气节点</th><th style="text-align:left;">现代音近似</th></tr></thead><tbody><tr><td style="text-align:left;">1</td><td style="text-align:left;"><strong>黄钟</strong></td><td style="text-align:left;">阳律</td><td style="text-align:left;">十一月</td><td style="text-align:left;">子</td><td style="text-align:left;">冬至</td><td style="text-align:left;">C</td></tr><tr><td style="text-align:left;">2</td><td style="text-align:left;"><strong>大吕</strong></td><td style="text-align:left;">阴吕</td><td style="text-align:left;">十二月</td><td style="text-align:left;">丑</td><td style="text-align:left;">大寒</td><td style="text-align:left;">C#</td></tr><tr><td style="text-align:left;">3</td><td style="text-align:left;"><strong>太簇</strong></td><td style="text-align:left;">阳律</td><td style="text-align:left;">正月</td><td style="text-align:left;">寅</td><td style="text-align:left;">雨水</td><td style="text-align:left;">D</td></tr><tr><td style="text-align:left;">4</td><td style="text-align:left;"><strong>夹钟</strong></td><td style="text-align:left;">阴吕</td><td style="text-align:left;">二月</td><td style="text-align:left;">卯</td><td style="text-align:left;">春分</td><td style="text-align:left;">D#</td></tr><tr><td style="text-align:left;">5</td><td style="text-align:left;"><strong>姑洗</strong></td><td style="text-align:left;">阳律</td><td style="text-align:left;">三月</td><td style="text-align:left;">辰</td><td style="text-align:left;">谷雨</td><td style="text-align:left;">E</td></tr><tr><td style="text-align:left;">6</td><td style="text-align:left;"><strong>仲吕</strong></td><td style="text-align:left;">阴吕</td><td style="text-align:left;">四月</td><td style="text-align:left;">巳</td><td style="text-align:left;">小满</td><td style="text-align:left;">F</td></tr><tr><td style="text-align:left;">7</td><td style="text-align:left;"><strong>蕤宾</strong></td><td style="text-align:left;">阳律</td><td style="text-align:left;">五月</td><td style="text-align:left;">午</td><td style="text-align:left;">夏至</td><td style="text-align:left;">F#</td></tr><tr><td style="text-align:left;">8</td><td style="text-align:left;"><strong>林钟</strong></td><td style="text-align:left;">阴吕</td><td style="text-align:left;">六月</td><td style="text-align:left;">未</td><td style="text-align:left;">大暑</td><td style="text-align:left;">G</td></tr><tr><td style="text-align:left;">9</td><td style="text-align:left;"><strong>夷则</strong></td><td style="text-align:left;">阳律</td><td style="text-align:left;">七月</td><td style="text-align:left;">申</td><td style="text-align:left;">处暑</td><td style="text-align:left;">G#</td></tr><tr><td style="text-align:left;">10</td><td style="text-align:left;"><strong>南吕</strong></td><td style="text-align:left;">阴吕</td><td style="text-align:left;">八月</td><td style="text-align:left;">酉</td><td style="text-align:left;">秋分</td><td style="text-align:left;">A</td></tr><tr><td style="text-align:left;">11</td><td style="text-align:left;"><strong>无射</strong></td><td style="text-align:left;">阳律</td><td style="text-align:left;">九月</td><td style="text-align:left;">戌</td><td style="text-align:left;">霜降</td><td style="text-align:left;">A#</td></tr><tr><td style="text-align:left;">12</td><td style="text-align:left;"><strong>应钟</strong></td><td style="text-align:left;">阴吕</td><td style="text-align:left;">十月</td><td style="text-align:left;">亥</td><td style="text-align:left;">小雪</td><td style="text-align:left;">B</td></tr></tbody></table><h3 id="_3-5-黄钟-万律之祖-一年之始" tabindex="-1">3.5 黄钟：万律之祖，一年之始 <a class="header-anchor" href="#_3-5-黄钟-万律之祖-一年之始" aria-label="Permalink to &quot;3.5 黄钟：万律之祖，一年之始&quot;">​</a></h3><p>十二律中，<strong>黄钟</strong>地位最高，是所有律的起点与基准。</p><blockquote><p>【原典】《史记·律书》<br> 【原文】&quot;黄钟者，阳气踵黄泉而出也。&quot;<br> 【版本】西汉·司马迁撰</p></blockquote><p><strong>&quot;阳气踵黄泉而出&quot;</strong>——<br> 冬至之时，阳气从地下最深处（黄泉）开始萌动，<br> 如脚踵蹬地，破土而出。<br> 黄钟，就是这一刻天地之气发出的第一声。</p><p>黄钟的对应：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>时间：冬至（十一月·子月）</span></span>
<span class="line"><span>方位：正北</span></span>
<span class="line"><span>五行：水（水为万物之源）</span></span>
<span class="line"><span>意义：一阳初生，万律之祖，一年之气从此启动</span></span></code></pre></div><p>这就是为什么古代历法以<strong>冬至</strong>为起算点——<br> 不是人为规定，而是因为黄钟一响，<br> 天地之气的新一轮循环真正开始了。</p><h2 id="四、三分损益法-律管的数学秘密" tabindex="-1">四、三分损益法：律管的数学秘密 <a class="header-anchor" href="#四、三分损益法-律管的数学秘密" aria-label="Permalink to &quot;四、三分损益法：律管的数学秘密&quot;">​</a></h2><p>这是中华文明在声学数学上最令人自豪的成就之一。</p><h3 id="_4-1-问题-十二律的音高从哪里来" tabindex="-1">4.1 问题：十二律的音高从哪里来？ <a class="header-anchor" href="#_4-1-问题-十二律的音高从哪里来" aria-label="Permalink to &quot;4.1 问题：十二律的音高从哪里来？&quot;">​</a></h3><p>十二律不是拍脑袋定的。<br> 先人用一套严密的数学方法，从黄钟出发，逐步推算出全部十二律的音高——这套方法叫做<strong>三分损益法</strong>。</p><h3 id="_4-2-原理-两个操作-交替进行" tabindex="-1">4.2 原理：两个操作，交替进行 <a class="header-anchor" href="#_4-2-原理-两个操作-交替进行" aria-label="Permalink to &quot;4.2 原理：两个操作，交替进行&quot;">​</a></h3><blockquote><p>【原典】《管子·地员篇》<br> 【原文】&quot;凡将起五音，凡首，先主一而三之，四开以合九九，以是生黄钟小素之首，以成宫。三分而益之以一，为百有八，为徵。不无有三分而去其乘，适足，以是生商。有三分，而复于其所，以是成羽。有三分，去其乘，适足，以是成角。&quot;<br> 【版本】战国·管仲撰（存疑，今本为后人整理）</p></blockquote><p>用现代语言解释，三分损益法只有两个操作：</p><p><strong>① 三分损一（下生）</strong><br> 取当前律管长度的 $$ \\frac{2}{3} $$<br> → 管变短，音高<strong>升高</strong>（约升高纯五度）</p><p><strong>② 三分益一（上生）</strong><br> 取当前律管长度的 $$ \\frac{4}{3} $$<br> → 管变长，音高<strong>降低</strong>（约降低纯四度）</p><p>两个操作交替进行，从黄钟出发，<br> 依次推出全部十二律。</p><h3 id="_4-3-推算过程-完整版" tabindex="-1">4.3 推算过程（完整版） <a class="header-anchor" href="#_4-3-推算过程-完整版" aria-label="Permalink to &quot;4.3 推算过程（完整版）&quot;">​</a></h3><p>设黄钟律管长度基准为 <strong>81</strong>（古人取 $$ 9 \\times 9 = 81 $$，九为阳数之极）：</p><table tabindex="0"><thead><tr><th style="text-align:left;">步骤</th><th style="text-align:left;">操作</th><th style="text-align:left;">律名</th><th style="text-align:left;">长度（近似）</th><th style="text-align:left;">阴阳</th></tr></thead><tbody><tr><td style="text-align:left;">起点</td><td style="text-align:left;">—</td><td style="text-align:left;"><strong>黄钟</strong></td><td style="text-align:left;">81</td><td style="text-align:left;">阳</td></tr><tr><td style="text-align:left;">1</td><td style="text-align:left;">×2/3（损）</td><td style="text-align:left;"><strong>林钟</strong></td><td style="text-align:left;">54</td><td style="text-align:left;">阴</td></tr><tr><td style="text-align:left;">2</td><td style="text-align:left;">×4/3（益）</td><td style="text-align:left;"><strong>太簇</strong></td><td style="text-align:left;">72</td><td style="text-align:left;">阳</td></tr><tr><td style="text-align:left;">3</td><td style="text-align:left;">×2/3（损）</td><td style="text-align:left;"><strong>南吕</strong></td><td style="text-align:left;">48</td><td style="text-align:left;">阴</td></tr><tr><td style="text-align:left;">4</td><td style="text-align:left;">×4/3（益）</td><td style="text-align:left;"><strong>姑洗</strong></td><td style="text-align:left;">64</td><td style="text-align:left;">阳</td></tr><tr><td style="text-align:left;">5</td><td style="text-align:left;">×2/3（损）</td><td style="text-align:left;"><strong>应钟</strong></td><td style="text-align:left;">42.67</td><td style="text-align:left;">阴</td></tr><tr><td style="text-align:left;">6</td><td style="text-align:left;">×4/3（益）</td><td style="text-align:left;"><strong>蕤宾</strong></td><td style="text-align:left;">56.89</td><td style="text-align:left;">阳</td></tr><tr><td style="text-align:left;">7</td><td style="text-align:left;">×4/3（益）</td><td style="text-align:left;"><strong>大吕</strong></td><td style="text-align:left;">75.85</td><td style="text-align:left;">阴</td></tr><tr><td style="text-align:left;">8</td><td style="text-align:left;">×2/3（损）</td><td style="text-align:left;"><strong>夷则</strong></td><td style="text-align:left;">50.57</td><td style="text-align:left;">阳</td></tr><tr><td style="text-align:left;">9</td><td style="text-align:left;">×4/3（益）</td><td style="text-align:left;"><strong>夹钟</strong></td><td style="text-align:left;">67.43</td><td style="text-align:left;">阴</td></tr><tr><td style="text-align:left;">10</td><td style="text-align:left;">×2/3（损）</td><td style="text-align:left;"><strong>无射</strong></td><td style="text-align:left;">44.95</td><td style="text-align:left;">阳</td></tr><tr><td style="text-align:left;">11</td><td style="text-align:left;">×4/3（益）</td><td style="text-align:left;"><strong>仲吕</strong></td><td style="text-align:left;">59.93</td><td style="text-align:left;">阴</td></tr></tbody></table><p>十二律全部推出。</p>`,73)),e("blockquote",null,[s(n,{style:{color:"rgb(89, 89, 89)"}},{default:a(()=>[...t[11]||(t[11]=[l("⚠️",-1)])]),_:1}),s(n,{style:{color:"rgb(89, 89, 89)"}}),t[14]||(t[14]=l("**",-1)),s(n,{style:{color:"rgb(89, 89, 89)"}},{default:a(()=>[...t[12]||(t[12]=[l("说明：",-1)])]),_:1}),t[15]||(t[15]=l("**",-1)),s(n,{style:{color:"rgb(89, 89, 89)"}},{default:a(()=>[...t[13]||(t[13]=[l(' 蕤宾→大吕处连续两次"益"，是三分损益法中著名的"蕤宾还宫"问题。蕤宾位于夏至（阴阳转折点），其上生下生历代有争议，《汉书·律历志》与《淮南子》处理方式略有不同。此处按《汉书》通行算法呈现。',-1)])]),_:1})]),t[18]||(t[18]=d(`<h3 id="_4-4-一个诚实的说明-黄钟不能还原" tabindex="-1">4.4 一个诚实的说明：黄钟不能还原 <a class="header-anchor" href="#_4-4-一个诚实的说明-黄钟不能还原" aria-label="Permalink to &quot;4.4 一个诚实的说明：黄钟不能还原&quot;">​</a></h3><p>先人在推算过程中，发现了一个问题：<br> 按三分损益法推出十二律后，第十三律（仲吕再损）理论上应回到黄钟，但实际得到的值是 <strong>59.93 × 2/3 ≈ 39.95</strong>，而黄钟的一半是 <strong>40.5</strong>——两者不相等，存在微小误差。</p><p>这就是著名的**&quot;黄钟不能还原&quot;<strong>问题，也称</strong>&quot;五度相生律的音差&quot;**。</p><p>先人没有回避这个问题，历代乐律学家持续探索了近两千年，直到明代<strong>朱载堉</strong>（1536—1611年）发明了<strong>十二平均律</strong>，用等比数列 $$ \\sqrt[12]{2} $$ 精确等分八度，从数学上彻底解决了这个问题——比西方数学家早了约半个世纪。</p><blockquote><p>这是中华文明在数学与声学领域的一项世界级成就，值得我们每一个中国人知道。</p></blockquote><p>详见 <strong>C-07·五音十二律</strong> 的完整数学推导。</p><h2 id="五、核心数理-五音-×-十二律-六十" tabindex="-1">五、核心数理：五音 × 十二律 = 六十 <a class="header-anchor" href="#五、核心数理-五音-×-十二律-六十" aria-label="Permalink to &quot;五、核心数理：五音 × 十二律 = 六十&quot;">​</a></h2><p>这是本篇最关键的结构，也是下一篇纳音五行的底层逻辑。</p><h3 id="_5-1-旋相为宫-每个律都可以做主音" tabindex="-1">5.1 旋相为宫：每个律都可以做主音 <a class="header-anchor" href="#_5-1-旋相为宫-每个律都可以做主音" aria-label="Permalink to &quot;5.1 旋相为宫：每个律都可以做主音&quot;">​</a></h3><p>十二律中，任何一律都可以作为&quot;宫音&quot;（主音）的起点，以它为基础，展开完整的五音音阶。 这叫做&quot;旋相为宫&quot;。</p><blockquote><p>【原典】《三命通会·总论纳音》<br> 【原文】&quot;尝观《笔谈》论六十甲子纳音，本六十律，旋相为宫法也。一律含五音，凡气始于东方而右行，音起于西方而左行，阴阳相错而生变化。&quot;<br> 【版本】明·万民英撰，《钦定四库全书》本</p></blockquote><p><strong>&quot;旋相为宫&quot;的数学结果：</strong></p><p>$ 12 \\text{（律）} \\times 5 \\text{（音）} = 60 \\text{（独立音位）} $</p><p>十二律，每律各含五音，共产生 <strong>60个独立的音律位置</strong>。</p><h3 id="_5-2-六十音位-对应-六十甲子" tabindex="-1">5.2 六十音位 对应 六十甲子 <a class="header-anchor" href="#_5-2-六十音位-对应-六十甲子" aria-label="Permalink to &quot;5.2 六十音位 对应 六十甲子&quot;">​</a></h3><p>这60个音律位置，恰好对应<strong>六十甲子</strong>的60对干支。</p><p>先人的对应逻辑：</p><ul><li>天地之气在时间中的运行 → 用六十甲子描述（时间坐标）</li><li>天地之气在声音中的振动 → 用六十音位描述（音律坐标）</li><li>两套坐标，描述同一件事 → 一一对应</li><li>每对干支，有其对应的音律位置</li><li>每个音律位置，有其五行属性（宫=土·商=金·角=木·徵=火·羽=水）</li><li>纳音五行 = 每对干支的&quot;音律五行身份&quot;</li></ul><h3 id="_5-3-气与音的相反方向" tabindex="-1">5.3 气与音的相反方向 <a class="header-anchor" href="#_5-3-气与音的相反方向" aria-label="Permalink to &quot;5.3 气与音的相反方向&quot;">​</a></h3><p>《三命通会》引《笔谈》的这段话，还揭示了一个深刻的结构：</p><blockquote><p>气始于东方而右行，音起于西方而左行，阴阳相错而生变化。</p></blockquote><table tabindex="0"><thead><tr><th style="text-align:left;">维度</th><th style="text-align:left;">起点</th><th style="text-align:left;">方向</th><th style="text-align:left;">顺序</th></tr></thead><tbody><tr><td style="text-align:left;">五行之<strong>气</strong></td><td style="text-align:left;">东方（木）</td><td style="text-align:left;">右行（顺时针）</td><td style="text-align:left;">木→火→土→金→水</td></tr><tr><td style="text-align:left;">五行之<strong>音</strong></td><td style="text-align:left;">西方（金）</td><td style="text-align:left;">左行（逆时针）</td><td style="text-align:left;">金→火→木→水→土</td></tr></tbody></table><p>气与音，起点相反，方向相反——<br> 正因为这种相反，阴阳相错，<br> 才产生了六十种变化，而不是简单的重复。</p><p>这是先人对宇宙运行规律的深刻洞察：<br><strong>对立，是产生变化与丰富性的根本。</strong></p><h2 id="六、候气法-用律管感知节气" tabindex="-1">六、候气法：用律管感知节气 <a class="header-anchor" href="#六、候气法-用律管感知节气" aria-label="Permalink to &quot;六、候气法：用律管感知节气&quot;">​</a></h2><p>这是五音六律体系中，最令现代人震撼的实践——先人用律管，来<strong>验证节气的到来</strong>。</p><h3 id="_6-1-操作方法" tabindex="-1">6.1 操作方法 <a class="header-anchor" href="#_6-1-操作方法" aria-label="Permalink to &quot;6.1 操作方法&quot;">​</a></h3><blockquote><p>【原典】《后汉书·律历志》<br> 【原文】&quot;候气之法：为室三重，涂衅必周，密布缇缦。室中以木为案，每律各一，内端如地，从其方位，加律其上，以葭莩灰抑其内端，案历而候之。气至者，灰动。其为气所动者，其灰散，人及风所动者，其灰聚。&quot;<br> 【版本】南朝宋·范晔撰</p></blockquote><p><strong>操作步骤（现代语言还原）：</strong></p><ol><li>建造一间三层隔音密室，四壁涂封严密，内挂红色帷幔</li><li>室内设木架，按方位摆放十二根律管</li><li>每根律管内端（朝下的一端）填入<strong>芦苇内膜灰</strong>（葭莩灰，极轻极细）</li><li>按历法推算，等待对应节气</li><li>节气到来时，对应律管内的灰<strong>自动飞散</strong></li></ol><p><strong>判断标准：</strong></p><ul><li>灰<strong>散开</strong>→ 天地之气所动，节气到来</li><li>灰<strong>聚拢</strong>→ 人为或风力所动，不算</li></ul><h3 id="_6-2-为什么灰会动" tabindex="-1">6.2 为什么灰会动？ <a class="header-anchor" href="#_6-2-为什么灰会动" aria-label="Permalink to &quot;6.2 为什么灰会动？&quot;">​</a></h3><p>这是一个至今仍有争议的问题。<br> 古人的解释是：天地之气与律管产生<strong>共鸣</strong>，气的振动带动了管内的灰。</p><p>现代学界对候气法的机制尚无定论，推测可能与以下因素有关：</p><p>大气压的季节性微变、地温变化引起的气流扰动，或极细灰粉对微小振动的高度敏感性。亦有学者认为此法的有效性本身仍需进一步实证研究。</p><p>无论机制如何，这套方法在古代被长期实践，说明它在实际操作中是<strong>有效的</strong>。</p><p>先人用这种方式告诉我们：<br> **声音，是天地之气可以被感知的形态。<br> **<strong>律管，是聆听天地的耳朵。</strong></p><h3 id="_6-3-十二律与节气对应" tabindex="-1">6.3 十二律与节气对应 <a class="header-anchor" href="#_6-3-十二律与节气对应" aria-label="Permalink to &quot;6.3 十二律与节气对应&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">律名</th><th style="text-align:left;">月份</th><th style="text-align:left;">主要节气</th><th style="text-align:left;">天地之气状态</th></tr></thead><tbody><tr><td style="text-align:left;">黄钟</td><td style="text-align:left;">十一月</td><td style="text-align:left;"><strong>冬至</strong></td><td style="text-align:left;">一阳初生，万律之始</td></tr><tr><td style="text-align:left;">大吕</td><td style="text-align:left;">十二月</td><td style="text-align:left;">大寒</td><td style="text-align:left;">阴气极盛，阳气渐升</td></tr><tr><td style="text-align:left;">太簇</td><td style="text-align:left;">正月</td><td style="text-align:left;">雨水</td><td style="text-align:left;">阳气渐升，万物萌动</td></tr><tr><td style="text-align:left;">夹钟</td><td style="text-align:left;">二月</td><td style="text-align:left;"><strong>春分</strong></td><td style="text-align:left;">阴阳平衡，生发之时</td></tr><tr><td style="text-align:left;">姑洗</td><td style="text-align:left;">三月</td><td style="text-align:left;">谷雨</td><td style="text-align:left;">木气旺盛，洁净万物</td></tr><tr><td style="text-align:left;">仲吕</td><td style="text-align:left;">四月</td><td style="text-align:left;">小满</td><td style="text-align:left;">阳气充盈，万物丰满</td></tr><tr><td style="text-align:left;">蕤宾</td><td style="text-align:left;">五月</td><td style="text-align:left;"><strong>夏至</strong></td><td style="text-align:left;">阳极将衰，阴气初生</td></tr><tr><td style="text-align:left;">林钟</td><td style="text-align:left;">六月</td><td style="text-align:left;">大暑</td><td style="text-align:left;">火气最旺，暑热极盛</td></tr><tr><td style="text-align:left;">夷则</td><td style="text-align:left;">七月</td><td style="text-align:left;">处暑</td><td style="text-align:left;">阳气收敛，秋意渐浓</td></tr><tr><td style="text-align:left;">南吕</td><td style="text-align:left;">八月</td><td style="text-align:left;"><strong>秋分</strong></td><td style="text-align:left;">阴阳再平衡，收藏之时</td></tr><tr><td style="text-align:left;">无射</td><td style="text-align:left;">九月</td><td style="text-align:left;">霜降</td><td style="text-align:left;">阳气将尽，万物凋零</td></tr><tr><td style="text-align:left;">应钟</td><td style="text-align:left;">十月</td><td style="text-align:left;">小雪</td><td style="text-align:left;">阴气极盛，万物归藏</td></tr></tbody></table><h2 id="七、跨体系接口" tabindex="-1">七、跨体系接口 <a class="header-anchor" href="#七、跨体系接口" aria-label="Permalink to &quot;七、跨体系接口&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">体系</th><th style="text-align:left;">五音六律的作用</th><th style="text-align:left;">具体说明</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>纳音五行（19）</strong></td><td style="text-align:left;"><strong>直接底层</strong></td><td style="text-align:left;">12律 × 5音 = 60，对应六十甲子；气与音的相反方向决定纳音顺序</td></tr><tr><td style="text-align:left;"><strong>二十四节气（14）</strong></td><td style="text-align:left;">时间验证</td><td style="text-align:left;">候气法以律管验证节气；十二律与十二月一一对应</td></tr><tr><td style="text-align:left;"><strong>历法体系（15）</strong></td><td style="text-align:left;">数理基础</td><td style="text-align:left;">&quot;律历合一&quot;——律数即历数，《汉书·律历志》合律与历为一志</td></tr><tr><td style="text-align:left;"><strong>黄帝内经</strong></td><td style="text-align:left;">五音治病</td><td style="text-align:left;">宫商角徵羽对应五脏；五音疗愈的理论根基</td></tr><tr><td style="text-align:left;"><strong>礼乐制度</strong></td><td style="text-align:left;">政治核心</td><td style="text-align:left;">《周礼》六律六同是雅乐制度的基础；律正则礼正</td></tr><tr><td style="text-align:left;"><strong>奇门遁甲</strong></td><td style="text-align:left;">间接背景</td><td style="text-align:left;">九宫与律吕的数理关联；宫音居中统御的结构</td></tr></tbody></table><blockquote><p>【原典】《汉书·律历志》<br> 【原文】&quot;律历之法，所以通神明，顺阴阳，序万物，应天地，统大始者也。&quot;<br> 【版本】东汉·班固撰</p></blockquote><p>先人将&quot;律&quot;与&quot;历&quot;并列为一志，<br> 正是因为在他们的世界观里，<br> **音律与历法，是同一件事的两种表达——<br> **<strong>都是对天地节律的度量与记录。</strong></p><h2 id="八、现代视角-先人在做什么" tabindex="-1">八、现代视角：先人在做什么？ <a class="header-anchor" href="#八、现代视角-先人在做什么" aria-label="Permalink to &quot;八、现代视角：先人在做什么？&quot;">​</a></h2><p>读到这里，让我们退一步，用现代眼光看这整件事。</p><p>先人构建五音六律体系，本质上是在做一件事：</p><p><strong>建立一套&quot;宇宙振动频率的坐标系&quot;。</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>现代物理学的视角：</span></span>
<span class="line"><span>  万物皆振动（量子力学·波粒二象性）</span></span>
<span class="line"><span>  不同频率的振动，产生不同的物质形态与能量状态</span></span>
<span class="line"><span></span></span>
<span class="line"><span>先人的视角：</span></span>
<span class="line"><span>  天地之气有五种基本状态（五行）</span></span>
<span class="line"><span>  每种状态有其对应的声音频率（五音）</span></span>
<span class="line"><span>  一年十二个月，天地之气各有其频率（十二律）</span></span>
<span class="line"><span>  用律管感知这些频率，就能知道天地之气的状态</span></span></code></pre></div><p>两种视角，描述的是同一个宇宙。</p><p>先人没有频率计，没有示波器，但他们用<strong>律管</strong>感知天地之气的振动，用<strong>五音</strong>描述五种基本的宇宙能量状态，用<strong>三分损益法</strong>精确推算音律的数学结构，用<strong>候气法</strong>在实践中验证理论——</p><p><strong>这是一套从哲学到物理、从理论到实验的完整体系。</strong></p><p>我们不必用&quot;科学&quot;来为它背书，它本身就是先人的科学—— <strong>一种以&quot;气&quot;为基本单位、以&quot;律&quot;为度量工具的宇宙科学</strong>。</p><h2 id="九、本篇小结" tabindex="-1">九、本篇小结 <a class="header-anchor" href="#九、本篇小结" aria-label="Permalink to &quot;九、本篇小结&quot;">​</a></h2><ol><li>五音是什么：<br> 宫商角徵羽，五行在声音维度的投影<br> 对应土·金·木·火·水，以及五方·五季·五脏<br> 每个字，都是一幅宇宙图像</li><li>十二律是什么：<br> 一年十二月，每月一律，共十二个音律坐标<br> 黄钟为万律之祖，起于冬至，一阳初生<br> 六律（阳）+ 六吕（阴），阴阳相和</li><li>三分损益法：<br> 从黄钟出发，×2/3（损）与×4/3（益）交替推算<br> 推出全部十二律，是世界声学史上的重要成就<br> &quot;黄钟不能还原&quot;问题，由明代朱载堉以十二平均律解决</li><li>为什么重要：<br> 12律 × 5音 = 60 → 纳音五行的底层数学结构<br> 候气法 → 声音是先人感知天地节律的工具<br> 律历合一 → 音律与历法，是同一件事的两种表达</li></ol><hr><h2 id="引用来源" tabindex="-1">引用来源 <a class="header-anchor" href="#引用来源" aria-label="Permalink to &quot;引用来源&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">编号</th><th style="text-align:left;">来源</th><th style="text-align:left;">核心内容</th></tr></thead><tbody><tr><td style="text-align:left;">1</td><td style="text-align:left;">《史记·律书》，西汉·司马迁撰（中国哲学书电子化计划）</td><td style="text-align:left;">律的定义·黄钟·六律为万事根本</td></tr><tr><td style="text-align:left;">2</td><td style="text-align:left;">《吕氏春秋·古乐篇》，战国·吕不韦撰</td><td style="text-align:left;">伶伦截竹·十二律起源传说</td></tr><tr><td style="text-align:left;">3</td><td style="text-align:left;">《周礼·春官·大司乐》，郑玄注本（东汉）</td><td style="text-align:left;">六律六同·礼乐制度</td></tr><tr><td style="text-align:left;">4</td><td style="text-align:left;">《淮南子·天文训》，西汉·刘安撰，高诱注本（中国哲学书电子化计划）</td><td style="text-align:left;">十二律与十二月对应</td></tr><tr><td style="text-align:left;">5</td><td style="text-align:left;">《黄帝内经·素问·阴阳应象大论》，唐·王冰注本</td><td style="text-align:left;">五音与五行·五方·五脏对应</td></tr><tr><td style="text-align:left;">6</td><td style="text-align:left;">《礼记·月令》，西汉·戴圣编，郑玄注本（中国哲学书电子化计划）</td><td style="text-align:left;">五音与五季·月令对应</td></tr><tr><td style="text-align:left;">7</td><td style="text-align:left;">《管子·地员篇》，战国（存疑，今本为后人整理）</td><td style="text-align:left;">三分损益法·五音推算原理</td></tr><tr><td style="text-align:left;">8</td><td style="text-align:left;">《汉书·律历志》，东汉·班固撰</td><td style="text-align:left;">律历合一·律历之法的意义</td></tr><tr><td style="text-align:left;">9</td><td style="text-align:left;">《后汉书·律历志》，南朝宋·范晔撰</td><td style="text-align:left;">候气法·律管验证节气</td></tr><tr><td style="text-align:left;">10</td><td style="text-align:left;">《三命通会·总论纳音》，明·万民英撰，《钦定四库全书》本</td><td style="text-align:left;">六十甲子纳音本于六十律·旋相为宫·气与音的相反方向</td></tr><tr><td style="text-align:left;">11</td><td style="text-align:left;">《白虎通·礼乐》，东汉·班固撰</td><td style="text-align:left;">五音字义溯源</td></tr></tbody></table><hr><p><strong>下一篇：</strong> 19 · 纳音五行（本篇底层结构的直接应用）<br><strong>C系列扩展：</strong> C-07 · 五音十二律（三分损益法完整数学推导·朱载堉十二平均律）</p>`,60))])}const P=r(x,[["render",h]]);export{m as __pageData,P as default};
